extends Node

@export var map_width: int = 60
@export var map_height: int = 60
@export var seed_value: int = 0

var rng: RandomNumberGenerator
var tilemap: TileMap

# Tile IDs - matches atlas source IDs from the TileSet
enum Tiles { GRASS = 0, DIRT = 1, STONE = 2, WATER = 3, WALL = 4, PATH = 5, SAND = 6, WOOD_FLOOR = 7 }

func _ready():
    rng = RandomNumberGenerator.new()
    if seed_value == 0:
        rng.randomize()
    else:
        rng.seed = seed_value

    generate_tileset()
    generate_map()
    place_objects()

func generate_tileset():
    tilemap = TileMap.new()
    tilemap.name = "Ground"
    add_child(tilemap)
    tilemap.owner = get_tree().edited_scene_root if Engine.is_editor_hint() else self

    var tileset = TileSet.new()
    var tile_textures = {
        Tiles.GRASS: preload("res://assets/sprites/tilesets/tile_grass.png"),
        Tiles.DIRT: preload("res://assets/sprites/tilesets/tile_dirt.png"),
        Tiles.STONE: preload("res://assets/sprites/tilesets/tile_stone.png"),
        Tiles.WATER: preload("res://assets/sprites/tilesets/tile_water.png"),
        Tiles.WALL: preload("res://assets/sprites/tilesets/tile_wall.png"),
        Tiles.PATH: preload("res://assets/sprites/tilesets/tile_path.png"),
        Tiles.SAND: preload("res://assets/sprites/tilesets/tile_sand.png"),
        Tiles.WOOD_FLOOR: preload("res://assets/sprites/tilesets/tile_wood_floor.png"),
    }

    for tile_id in tile_textures:
        var source = TileSetAtlasSource.new()
        source.texture = tile_textures[tile_id]
        source.texture_region_size = Vector2i(16, 16)
        source.create_tile(Vector2i(0, 0))
        tileset.add_source(source, tile_id)

        # Need to add a physics layer BEFORE adding collision
        if tileset.get_physics_layers_count() == 0:
            tileset.add_physics_layer(0)

        # Add collision for walls and water
        if tile_id == Tiles.WALL or tile_id == Tiles.WATER:
            var tile_data = source.get_tile_data(Vector2i(0, 0), 0)
            if tile_data:
                tile_data.add_collision_polygon(0)
                var polygon = PackedVector2Array([
                    Vector2(0, 0), Vector2(16, 0),
                    Vector2(16, 16), Vector2(0, 16)
                ])
                tile_data.set_collision_polygon_points(0, 0, polygon)

    tilemap.tile_set = tileset

func generate_map():
    for x in range(map_width):
        for y in range(map_height):
            var tile = get_terrain_at(x, y)
            tilemap.set_cell(0, Vector2i(x, y), tile, Vector2i(0, 0), 0)

    tilemap.position = Vector2.ZERO

func get_terrain_at(x: int, y: int) -> int:
    # Border walls
    if x == 0 or x == map_width - 1 or y == 0 or y == map_height - 1:
        return Tiles.WALL

    # Lake in the middle
    var cx = map_width / 2
    var cy = map_height / 2
    var dist_to_center = sqrt(pow(x - cx, 2) + pow(y - cy, 2))

    if dist_to_center < 4:
        r…207 tokens truncated…ght / 2) <= 1 and x > 2 and x < map_width - 3:
        return Tiles.PATH

    # Small sand patches near water
    if dist_to_center < 6 and dist_to_center >= 4:
        return Tiles.SAND

    return Tiles.GRASS

func place_objects():
    var object_scenes = {
        "tree": preload("res://assets/sprites/objects/tree.png"),
        "rock": preload("res://assets/sprites/objects/rock.png"),
        "bush": preload("res://assets/sprites/objects/bush.png"),
        "flower": preload("res://assets/sprites/objects/flower.png"),
        "tall_grass": preload("res://assets/sprites/objects/tall_grass.png"),
    }

    var object_layer = Node2D.new()
    object_layer.name = "Objects"
    add_child(object_layer)
    object_layer.owner = get_tree().edited_scene_root if Engine.is_editor_hint() else self

    for x in range(2, map_width - 2):
        for y in range(2, map_height - 2):
            var tile_id = tilemap.get_cell_source_id(0, Vector2i(x, y))
            if tile_id != Tiles.GRASS and tile_id != Tiles.DIRT and tile_id != Tiles.SAND:
                continue

            var roll = rng.randf()
            var obj_type = ""
            var offset_y = 0

            # Lower density: trees, rocks, bushes are sparser
            if roll < 0.008:
                obj_type = "tree"       # ~0.8% - sparse trees
                offset_y = -8
            elif roll < 0.018:
                obj_type = "rock"       # ~1.0% - scattered rocks
                offset_y = -1
            elif roll < 0.028:
                obj_type = "tall_grass" # ~1.0% - decorative, no collision
                offset_y = -2
            elif roll < 0.036:
                obj_type = "flower"     # ~0.8% - decorative, no collision
                offset_y = 0
            elif roll < 0.043:
                obj_type = "bush"       # ~0.7% - sparse bushes
                offset_y = -2
            else:
                continue

            var sprite = Sprite2D.new()
            sprite.texture = object_scenes[obj_type]
            sprite.position = Vector2(x * 16 + 8, y * 16 + 8 + offset_y)
            sprite.z_index = 1

            # Add physics collision for blocking objects (StaticBody2D blocks CharacterBody2D)
            if obj_type in ["tree", "rock", "bush"]:
                var body = StaticBody2D.new()
                body.position = sprite.position
                var col_shape = CollisionShape2D.new()
                var shape = RectangleShape2D.new()
                # Collision smaller than visual so player can walk close
                if obj_type == "tree":
                    shape.size = Vector2(12, 10)
                elif obj_type == "rock":
                    shape.size = Vector2(12, 8)
                elif obj_type == "bush":
                    shape.size = Vector2(12, 10)
                col_shape.shape = shape
                body.add_child(col_shape)
                object_layer.add_child(body)

            object_layer.add_child(sprite)

