/**
 * 闇勫 (Skyward Spire) - HD Pixel Art Asset Generator v2
 * Octopath Traveler inspired style: larger sprites, rich colors, detailed shading
 * 
 * Run: node scripts/tools/generate_assets_v2.js
 */

const fs = require('fs');
const path = require('path');
const zlib = require('zlib');

// ====================== PNG ENCODING ======================

function crc32(data) {
    let crc = 0xFFFFFFFF;
    for (let i = 0; i < data.length; i++) {
        crc ^= data[i];
        for (let j = 0; j < 8; j++) {
            if (crc & 1) crc = (crc >>> 1) ^ 0xEDB88320;
            else crc >>>= 1;
        }
    }
    return (crc ^ 0xFFFFFFFF) >>> 0;
}

function writeU32BE(buf, off, val) {
    buf[off] = (val >>> 24) & 0xFF;
    buf[off+1] = (val >>> 16) & 0xFF;
    buf[off+2] = (val >>> 8) & 0xFF;
    buf[off+3] = val & 0xFF;
}

function makeChunk(type, data) {
    const len = data ? data.length : 0;
    const buf = Buffer.alloc(4 + 4 + len + 4);
    writeU32BE(buf, 0, len);
    buf.write(type, 4, 4, 'ascii');
    if (data) data.copy(buf, 8);
    const crcVal = crc32(buf.slice(4, 8 + len));
    writeU32BE(buf, 8 + len, crcVal);
    return buf;
}

function encodePNG(width, height, pixels) {
    const sig = Buffer.from([0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A]);
    const ihdr = Buffer.alloc(13);
    writeU32BE(ihdr, 0, width);
    writeU32BE(ihdr, 4, height);
    ihdr[8] = 8; ihdr[9] = 6; ihdr[10] = 0; ihdr[11] = 0; ihdr[12] = 0;
    const rawLen = (1 + width * 4) * height;
    const raw = Buffer.alloc(rawLen);
    for (let y = 0; y < height; y++) {
        raw[y * (1 + width * 4)] = 0;
        for (let x = 0; x < width; x++) {
            const si = (y * width + x) * 4;
            const di = y * (1 + width * 4) + 1 + x * 4;
            raw[di] = pixels[si]; raw[di+1] = pixels[si+1];
            raw[di+2] = pixels[si+2]; raw[di+3] = pixels[si+3];
        }
    }
    return Buffer.concat([sig, makeChunk('IHDR', ihdr), makeChunk('IDAT', zlib.deflateSync(raw)), makeChunk('IEND', null)]);
}

function rgba(w, h, r=0, g=0, b=0, a=0) {
    const buf = new Uint8Array(w * h * 4);
    for (let i = 0; i < w * h; i++) { buf[i*4]=r; buf[i*4+1]=g; buf[i*4+2]=b; buf[i*4+3]=a; }
    return buf;
}

function px(p, w, x, y, r, g, b, a=255) {
    const i = (y * w + x) * 4;
    p[i]=r; p[i+1]=g; p[i+2]=b; p[i+3]=a;
}

function rect(p, w, x, y, rw, rh, r, g, b, a=255) {
    for (let dy=0; dy<rh; dy++) for (let dx=0; dx<rw; dx++) px(p, w, x+dx, y+dy, r, g, b, a);
}

function savePNG(fn, w, h, p) {
    const d = path.dirname(fn);
    if (!fs.existsSync(d)) fs.mkdirSync(d, { recursive: true });
    fs.writeFileSync(fn, encodePNG(w, h, p));
    console.log(`  ${fn}`);
}

