function generatePlayerSprite() {
    const FW = 32, FH = 48, DIRS = 4;
    const W = FW * DIRS, H = FH;
    const p = rgba(W, H, 0, 0, 0, 0);
    for (let d = 0; d < DIRS; d++) {
        drawBody(p, W, d * FW, 0);
        drawHead(p, W, d * FW, 0, d);
    }
    return { p, w: W, h: H };
}

function generatePlayerIcon() {
    const W = 64, H = 64;
    const p = rgba(W, H);
    const spr = generatePlayerSprite();
    for (let sy = 0; sy < 48; sy++) {
        for (let sx = 0; sx < 32; sx++) {
            const si = (sy * 128 + sx) * 4;
            const r = spr.p[si], g = spr.p[si+1], b = spr.p[si+2], a = spr.p[si+3];
            if (a > 0) {
                // Scale with offsets
                for (let dy = 0; dy < 1; dy++) for (let dx = 0; dx < 2; dx++) {
                    px(p, W, sx*2+dx, sy+8, r, g, b, a);
                }
            }
        }
    }
    return p;
}

