function makeTile(type) {
    const S = 16;
    const p = rgba(S, S, 0, 0, 0, 255);
    const c = C;

    switch (type) {
        case 'grass':
            rect(p, S, 0, 0, S, S, c.gs1[0], c.gs1[1], c.gs1[2]);
            for (let y=0; y<16; y++) for (let x=y%2; x<16; x+=2) {
                px(p, S, x, y, c.gs2[0], c.gs2[1], c.gs2[2]);
            }
            px(p, S, 2, 3, c.gs3[0], c.gs3[1], c.gs3[2]);
            px(p, S, 8, 5, c.gs3[0], c.gs3[1], c.gs3[2]);
            px(p, S, 13, 2, c.gs3[0], c.gs3[1], c.gs3[2]);
            px(p, S, 5, 10, c.gs3[0], c.gs3[1], c.gs3[2]);
            px(p, S, 11, 12, c.gs3[0], c.gs3[1], c.gs3[2]);
            px(p, S, 3, 7, c.gs4[0], c.gs4[1], c.gs4[2]);
            px(p, S, 10, 3, c.gs4[0], c.gs4[1], c.gs4[2]);
            // Tiny flowers
            px(p, S, 4, 3, 230, 200, 80);
            px(p, S, 12, 9, 240, 180, 120);
            break;
        case 'dirt':
            rect(p, S, 0, 0, S, S, c.dt1[0], c.dt1[1], c.dt1[2]);
            for (let i=0; i<12; i++) {
                const dx = (i*3+2) % 15, dy = (i*5+1) % 15;
                px(p, S, dx, dy, c.dt2[0], c.dt2[1], c.dt2[2]);
            }
            px(p, S, 7, 3, c.dt3[0], c.dt3[1], c.dt3[2]);
            px(p, S, 4, 9, c.dt3[0], c.dt3[1], c.dt3[2]);
