        case 'stone':
            rect(p, S, 0, 0, S, S, c.st1[0], c.st1[1], c.st1[2]);
            rect(p, S, 2, 0, 12, 7, c.st3[0], c.st3[1], c.st3[2]);
            rect(p, S, 1, 7, 14, 9, c.st2[0], c.st2[1], c.st2[2]);
            rect(p, S, 0, 7, 16, 1, c.st4[0], c.st4[1], c.st4[2]);
            for (let i=0; i<5; i++) {
                px(p, S, i*3+1, i%4+1, c.st3[0]+20, c.st3[1]+20, c.st3[2]+20);
            }
            break;
        case 'water':
            rect(p, S, 0, 0, S, S, c.wt1[0], c.wt1[1], c.wt1[2]);
            rect(p, S, 0, 3, 5, 1, c.wt3[0], c.wt3[1], c.wt3[2]);
