            rect(p, S, 11, 13, 5, 1, c.wt4[0], c.wt4[1], c.wt4[2]);
            px(p, S, 7, 4, c.wt2[0], c.wt2[1], c.wt2[2]);
            px(p, S, 12, 9, c.wt2[0], c.wt2[1], c.wt2[2]);
            px(p, S, 4, 14, c.wt2[0], c.wt2[1], c.wt2[2]);
            break;
        case 'wall':
            rect(p, S, 0, 0, S, S, c.wl1[0], c.wl1[1], c.wl1[2]);
            rect(p, S, 0, 0, 8, 7, c.wl2[0], c.wl2[1], c.wl2[2]);
            rect(p, S, 8, 0, 8, 7, c.wl3[0], c.wl3[1], c.wl3[2]);
            rect(p, S, 4, 7, 8, 7, c.wl2[0], c.wl2[1], c.wl2[2]);
            rect(p, S, 0, 7, 4, 7, c.wl3[0], c.wl3[1], c.wl3[2]);
            rect(p, S, 0, 14, 8, 2, c.wl3[0], c.wl3[1], c.wl3[2]);
            rect(p, S, 8, 14, 8, 2, c.wl2[0], c.wl2[1], c.wl2[2]);
            rect(p, S, 0, 7, 16, 1, c.wl1[0], c.wl1[1], c.wl1[2]);
            rect(p, S, 8, 0, 1, 7, c.wl1[0], c.wl1[1], c.wl1[2]);
            rect(p, S, 4, 7, 1, 7, c.wl1[0], c.wl1[1], c.wl1[2]);
            break;
        case 'path':
            rect(p, S, 0, 0, S, S, c.pt1[0], c.pt1[1], c.pt1[2]);
            for (let i=0; i<8; i++) px(p, S, (i*3)%14+1, (i*5)%14+1, c.pt2[0], c.pt2[1], c.pt2[2]);
            break;
        case 'sand':
            rect(p, S, 0, 0, S, S, c.sd1[0], c.sd1[1], c.sd1[2]);
            for (let i=0; i<10; i++) px(p, S, (i*4)%14+1, (i*3)%14+1, c.sd2[0], c.sd2[1], c.sd2[2]);
            break;
        case 'wood_floor':
            rect(p, S, 0, 0, S, S, c.wf1[0], c.wf1[1], c.wf1[2]);
            rect(p, S, 0, 2, 16, 1, c.wf2[0], c.wf2[1], c.wf2[2]);
            rect(p, S, 0, 6, 16, 1, c.wf2[0], c.wf2[1], c.wf2[2]);
            rect(p, S, 0, 10, 16, 1, c.wf2[0], c.wf2[1], c.wf2[2]);
