    rect(p, W, 15, 10, 3, 12, c.gs2[0], c.gs2[1], c.gs2[2]);
    px(p, W, 5, 7, c.gs3[0], c.gs3[1], c.gs3[2]);
    px(p, W, 9, 3, c.gs3[0], c.gs3[1]+15, c.gs3[2]+5);
    px(p, W, 13, 5, c.gs3[0], c.gs3[1], c.gs3[2]);
    px(p, W, 16, 9, c.gs3[0], c.gs3[1], c.gs3[2]);
    return p;
}

// ====================== GAME ICON ======================

function makeIcon() {
    const W = 256, H = 256;
    const p = rgba(W, H);
    // Sky gradient
    for (let y=0; y<H; y++) {
        const t = y / H;
        const r = 10 + t * 25, g = 8 + t * 20, b = 30 + t * 35;
        rect(p, W, 0, y, W, 1, r, g, b);
    }
    // Tower (scaled up from previous)
    rect(p, W, 72, 120, 112, 120, 80, 75, 90);
    rect(p, W, 84, 60, 88, 60, 90, 85, 100);
    rect(p, W, 96, 20, 64, 40, 100, 95, 110);
    rect(p, W, 112, 0, 32, 20, 120, 115, 130);
    // Glowing windows
    rect(p, W, 92, 70, 16, 16, 255, 220, 100);
    rect(p, W, 148, 70, 16, 16, 255, 220, 100);
    rect(p, W, 92, 100, 16, 16, 255, 200, 80);
    rect(p, W, 148, 100, 16, 16, 255, 200, 80);
    rect(p, W, 104, 130, 48, 24, 255, 200, 80);
    rect(p, W, 112, 200, 32, 40, 60, 55, 70);
    // Ground
    rect(p, W, 0, 230, W, 26, 40, 50, 30);
    // Stars with glow
    const stars = [[20,30],[50,16],[200,24],[220,50],[36,80],[210,100],[16,140],[230,160],[40,180],[216,200]];
    for (const [sx, sy] of stars) {
        for (let dx=-1; dx<=1; dx++) for (let dy=-1; dy<=1; dy++) {
            px(p, W, sx+dx, sy+dy, 180, 180, 255);
        }
        px(p, W, sx, sy, 255, 255, 255);
        px(p, W, sx+1, sy, 255, 255, 255);
        px(p, W, sx, sy+1, 255, 255, 255);
    }
    // Moon
    rect(p, W, 190, 36, 24, 24, 240, 235, 220);
    px(p, W, 200, 40, 200, 200, 200);
    return p;
}

// ====================== MAIN ======================

function main() {
    const D = 'D:\\vibe coding\\2D game';
    console.log('\n=== 闇勫 HD Asset Generator v2 (Octopath Traveler Style) ===\n');

    // Clear old generated sprites
    const dirs = [
        `${D}\\assets\\sprites\\player`,
        `${D}\\assets\\sprites\\tilesets`,
        `${D}\\assets\\sprites\\objects`,
        `${D}\\assets\\icons`
    ];
    for (const dir of dirs) {
        if (fs.existsSync(dir)) {
            const files = fs.readdirSync(dir).filter(f => f.endsWith('.png'));
            for (const f of files) fs.unlinkSync(`${dir}\\${f}`);
        }
    }

    // Remove old .import files too
    const importDir = `${D}\\.godot\\imported`;
    if (fs.existsSync(importDir)) {
        const files = fs.readdirSync(importDir).filter(f => f.endsWith('.ctex') || f.endsWith('.md5'));
        for (const f of files) fs.unlinkSync(`${importDir}\\${f}`);
    }

    console.log('[1/5] Player sprites (32x48, 4 dirs)...');
    const player = generatePlayerSprite();
    savePNG(`${D}\\assets\\sprites\\player\\player_spritesheet.png`, player.w, player.h, player.p);
    savePNG(`${D}\\assets\\sprites\\player\\player_icon.png`, 64, 64, generatePlayerIcon());

    console.log('[2/5] Terrain tiles (16x16, detailed)...');
    for (const t of ['grass','dirt','stone','water','wall','path','sand','wood_floor']) {
        savePNG(`${D}\\assets\\sprites\\tilesets\\tile_${t}.png`, 16, 16, makeTile(t));
    }

    console.log('[3/5] Objects...');
    savePNG(`${D}\\assets\\sprites\\objects\\tree.png`, 32, 48, makeTree());
    savePNG(`${D}\\assets\\sprites\\objects\\rock.png`, 28, 22, makeRock());
    savePNG(`${D}\\assets\\sprites\\objects\\bush.png`, 28, 24, makeBush());
    savePNG(`${D}\\assets\\sprites\\objects\\flower.png`, 16, 16, makeFlower());
    savePNG(`${D}\\assets\\sprites\\objects\\tall_grass.png`, 20, 24, makeTallGrass());

    console.log('[4/5] Game icon (256x256)...');
    savePNG(`${D}\\assets\\icons\\icon.png`, 256, 256, makeIcon());

    console.log('\n鉁?HD assets generated! Re-import in Godot required.\n');
}

main();

